using System.Diagnostics;
using System.Diagnostics.Metrics;
using OtelCorrelationLab;
using Xunit;
public sealed class TelemetryTests { [Fact] public void Activity_carries_operation_and_bounded_tag() { Activity? stopped = null; using var l = new ActivityListener { ShouldListenTo = s => s.Name == "Atlas.Orders", Sample = static (ref ActivityCreationOptions<ActivityContext> _) => ActivitySamplingResult.AllData, ActivityStopped = a => stopped = a }; ActivitySource.AddActivityListener(l); new OrderProcessor().Process("order-1"); Assert.Equal("order.process", stopped!.OperationName); Assert.Equal("order-1", stopped.GetTagItem("order.id")); } [Fact] public void Metrics_emit_counter_and_duration() { var names = new List<string>(); using var listener = new MeterListener(); listener.InstrumentPublished = (i, x) => { if (i.Meter.Name == "Atlas.Orders") { names.Add(i.Name); x.EnableMeasurementEvents(i); } }; listener.SetMeasurementEventCallback<long>((_, _, _, _) => { }); listener.SetMeasurementEventCallback<double>((_, _, _, _) => { }); listener.Start(); new OrderProcessor().Process("x"); Assert.Contains("orders.processed", names); Assert.Contains("orders.duration", names); } [Fact] public void Trace_ids_differ_between_root_operations() { using var l = new ActivityListener { ShouldListenTo = _ => true, Sample = static (ref ActivityCreationOptions<ActivityContext> _) => ActivitySamplingResult.AllData }; ActivitySource.AddActivityListener(l); var p = new OrderProcessor(); Assert.NotEqual(p.Process("a"), p.Process("b")); } [Fact] public void No_listener_produces_unsampled_marker() { Assert.Equal("unsampled", new OrderProcessor().Process("x")); } }
